//! 🧪️ The actual installed producer publishes its native cursor and reply before interruption.
use semio_framework_value_factory::*;
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
use std::sync::{Arc,atomic::{AtomicUsize,AtomicBool,Ordering}};
#[derive(FactoryPayloadRetirement)]
#[value(crate="semio_framework_value_factory")]
struct Producer{#[factory_owned]calls:AtomicUsize,#[factory_owned]recoveries:AtomicUsize,#[factory_owned]interrupt:AtomicBool,#[factory_owned]pointer:AtomicUsize}
impl ArtifactOwnedValueRetirementFactory<String> for Producer{
 fn retirement_birth_bytes(&self,value:&String)->usize{ArtifactOwnedValueRetirementFactory::retirement_birth_bytes(&OwnedValueRetirementFactory::<String>::default(),value)}
 fn retire_owned_work_demand(&self,value:&String)->Result<u64,ValueError>{OwnedValueRetirementFactory::<String>::default().retire_owned_work_demand(value)}
 fn retire_owned_demands(&self,value:&String)->Result<RetirementDemand,ValueError>{OwnedValueRetirementFactory::<String>::default().retire_owned_demands(value)}
 fn retire_owned<'reply>(&self,value:&mut Option<String>,effect:&mut RetainedAllocationEffect<'_>,reply:FactoryProducerReply<'reply,dyn ErasedSnapshotRetirement,OriginalRetirementFailure>)->FactoryProducerReplyComplete<'reply,OriginalRetirementFailure>{self.calls.fetch_add(1,Ordering::SeqCst);assert_eq!(value.as_ref().unwrap().as_ptr()as usize,self.pointer.load(Ordering::SeqCst));let complete=OwnedValueRetirementFactory::<String>::default().retire_owned(value,effect,reply);if self.interrupt.swap(false,Ordering::SeqCst){panic!("actual factory recorded its reply before interruption")}complete}
 fn recover_retire_owned<'reply>(&self,_:&mut Option<String>,_:&mut RetainedAllocationEffect<'_>,reply:FactoryProducerReply<'reply,dyn ErasedSnapshotRetirement,OriginalRetirementFailure>)->FactoryProducerReplyComplete<'reply,OriginalRetirementFailure>{self.recoveries.fetch_add(1,Ordering::SeqCst);reply.pending()}
}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn complete<T,E>(poll:RetainedWorkPoll<T,E>)->RetainedWorkOutcome<T,E>{match poll{RetainedWorkPoll::Complete(turn)=>turn,RetainedWorkPoll::Pending{..}=>panic!("fixture expected a recorded completed reply")}}
fn drain(owner:&mut dyn ErasedSnapshotRetirement,bank:&mut EffectBank){for _ in 0..512{if owner.terminal_is_empty(){return}let d=owner.next_demand(65536).unwrap();let g=grant(d);let work=owner.next_computational_work(65536).unwrap();let((turn,actual),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||bank.run(g,work,|effect|owner.close_step(effect)));let turn=complete(turn);let p=turn.result.unwrap().progress();assert_eq!(actual.unwrap_or(0),p.retained_capacity_bytes);bank.post(p,g,heap);assert_eq!(bank.take_admitted(),Some(true));}panic!("finite factory fixture failed to close")}
#[test]
fn resident_factory_owner_and_recorded_reply_survive_unwind_without_replay(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("fixture.json")).unwrap();let probe=fixture["probe"].as_u64().unwrap()as usize;let(_,observed)=semio_framework_value_testing_allocator::observe_retirement_allocations(||{let bytes=std::hint::black_box(vec![7u8;probe]);std::hint::black_box(&bytes);drop(bytes)});assert_eq!(observed,(probe,probe));
 let mut bank=EffectBank::new(Wallet::from_profile(&fixture["stock"]));let((mut original,source),held)=semio_framework_value_testing_allocator::observe_retirement_allocations(||{let value=fixture["body"].as_str().unwrap().to_owned();let source=Arc::new(Producer{calls:AtomicUsize::new(0),recoveries:AtomicUsize::new(0),interrupt:AtomicBool::new(true),pointer:AtomicUsize::new(value.as_ptr()as usize)});(Some(value),source)});let held_grant=bank.loan(1,65536);bank.post(RetainedCloneProgress{retained_capacity_bytes:held.0,..Default::default()},held_grant,held);
 let mut factory:Option<Arc<dyn ArtifactOwnedValueRetirementFactory<String>>>=Some(source.clone());let mut output=None;let g=grant(owned::FactoryOwnedRetirement::<String>::original_admission_demands(&original));let((turn,actual),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||bank.run(g,1,|effect|owned::FactoryOwnedRetirement::admit_original(&mut original,&mut factory,&mut output,effect)));let p=complete(turn).result.unwrap().progress();assert_eq!(actual,Some(p.retained_capacity_bytes));bank.post(p,g,heap);assert_eq!(bank.take_admitted(),Some(true));assert!(original.is_none()&&factory.is_none());
 let owner=output.as_mut().unwrap();let g=grant(owner.next_demand(65536).unwrap());let(interrupted,birth)=semio_framework_value_testing_allocator::observe_retirement_allocations(||std::panic::catch_unwind(std::panic::AssertUnwindSafe(||bank.run(g,1,|effect|owner.close_step(effect)))));assert!(interrupted.is_err());assert!(birth.0>0);assert_eq!(bank.actual(),Some(birth.0));let((turn,actual),recovery)=semio_framework_value_testing_allocator::observe_retirement_allocations(||bank.run(g,1,|effect|owner.close_step(effect)));let turn=complete(turn);assert_eq!(turn.work,fixture["work"][1].as_u64().unwrap()as u128);let p=turn.result.unwrap().progress();assert_eq!(recovery,(0,0));assert_eq!(actual,Some(birth.0));bank.post(p,g,birth);assert_eq!(bank.take_admitted(),Some(true));assert_eq!(source.calls.load(Ordering::SeqCst),fixture["calls"].as_u64().unwrap()as usize);assert_eq!(source.recoveries.load(Ordering::SeqCst),fixture["recoveries"].as_u64().unwrap()as usize);
 drain(owner.as_mut(),&mut bank);let g=grant(factory_ticket_demands(output.as_ref().unwrap(),65536).unwrap());let((turn,_),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||bank.run(g,1,|effect|close_factory_ticket(&mut output,effect)));bank.post(complete(turn).result.unwrap().progress(),g,heap);assert_eq!(bank.take_admitted(),Some(true));let mut final_source=retirement::controlled::ControlledRetirement::retain(FactoryAuthority::new(source));drain(&mut final_source,&mut bank);
}
